patch = '''from orders import quantities


def reserve(stock, order):
    counts = {}
    for sku, count in order:
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
            raise ValueError('invalid quantity')
        counts[sku] = counts.get(sku, 0) + count

    # Validate availability before mutating anything
    for sku, total in counts.items():
        if stock.get(sku, 0) < total:
            raise ValueError('unavailable')

    # All valid and available; now mutate
    for sku, total in counts.items():
        stock[sku] -= total

    return stock
'''

# Test it
import sys
sys.path.insert(0, '/workspace')

exec(patch)

# Basic
order = [('A', 5), ('B', 3)]
stock = {'A': 10, 'B': 3}
print(reserve(dict(stock), order))  # expect A=5, B=0

# Repeated SKU combined
order2 = [('A', 2), ('A', 3)]
stock2 = {'A': 4}
try:
    print(reserve(dict(stock2), order2))
except Exception as e:
    print(f"Error: {e}")  # expect unavailable (need 5, have 4)

# Repeated SKU sufficient
stock3 = {'A': 5}
print(reserve(dict(stock3), order2))  # expect A=0

# Negative quantity
try:
    reserve({'A': 10}, [('A', -1)])
except Exception as e:
    print(f"Error: {e}")  # expect invalid quantity

# Zero quantity
try:
    reserve({'A': 10}, [('A', 0)])
except Exception as e:
    print(f"Error: {e}")  # expect invalid quantity

# Non-integer
try:
    reserve({'A': 10}, [('A', 2.5)])
except Exception as e:
    print(f"Error: {e}")  # expect invalid quantity

# Atomicity: first SKU ok, second not — stock should be unchanged
stock4 = {'A': 10, 'B': 1}
order4 = [('A', 5), ('B', 3)]
try:
    reserve(dict(stock4), order4)
except Exception as e:
    print(f"Error: {e}")
print("stock after failed:", dict(stock4))  # expect A=10, B=1 (unchanged)
```

