def update_url(url,updates):
    parts=urlsplit(url)
    pairs=parse_qsl(parts.query, keep_blank_values=True)

    result=[]
    updated_keys=set()
    removed_keys=set(k for k,v in updates.items() if v is None)

    for key,value in pairs:
        if key in removed_keys:
            continue  # skip all occurrences of removed keys
        elif key in updates and key not in updated_keys:
            # Replace at first occurrence position; skip remaining occurrences
            result.append((key,str(updates[key])))
            updated_keys.add(key)
