            continue  # skip duplicate occurrences of already-updated keys
        else:
            result.append((key,value))

    # Append any keys that weren't in the original query
    for key,value in updates.items():
        if value is not None and key not in updated_keys:
            result.append((key,str(value)))

    return urlunsplit(parts._replace(query=urlencode(result)))
